const contactResult = $('Check Contact Duplicate').first().json;
const bookingResults = $('Check Booking Conflict').all().map(i => i.json);

const result = {
  // Contact duplicate info
  contact_found: !!contactResult.id,
  existing_contact: contactResult.id ? {
    id: contactResult.id,
    name: contactResult.name,
    phone: contactResult.phone,
    total_bookings: contactResult.total_bookings,
    last_booking_date: contactResult.last_booking_date
  } : null,

  // Booking conflict info
  booking_conflicts: bookingResults.filter(b => b.id).map(b => ({
    id: b.id,
    customer_name: b.customer_name,
    event_time: b.event_time,
    address: b.delivery_address,
    city: b.city,
    status: b.status
  })),
  has_conflicts: bookingResults.some(b => b.id),

  // Message for Telegram (Lithuanian)
  contact_message: contactResult.id 
    ? `Rastas esamas kontaktas: ${contactResult.name}, ${contactResult.total_bookings} užsakymai anksčiau.`
    : null,
  conflict_message: bookingResults.some(b => b.id)
    ? `⚠️ Jau yra ${bookingResults.filter(b => b.id).length} užsakymas(-ai) ${$('Execute Workflow Trigger').first().json.event_date}, ${$('Execute Workflow Trigger').first().json.city}: ${bookingResults.filter(b => b.id).map(b => `${b.customer_name} ${b.event_time}`).join(', ')}`
    : null
};

return [{ json: result }];
